package com.clinicbooking.medicalrecord.infrastructure.out.persistence;
import com.clinicbooking.medicalrecord.application.port.out.MedicalRecordRepositoryPort; import com.clinicbooking.medicalrecord.domain.*; import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.util.*;
@Repository public class MedicalRecordPersistenceAdapter implements MedicalRecordRepositoryPort {
 private final MedicalRecordJpaRepository jpa; private final MedicalPrescriptionJpaRepository prescriptions;
 public MedicalRecordPersistenceAdapter(MedicalRecordJpaRepository jpa,MedicalPrescriptionJpaRepository prescriptions){this.jpa=jpa;this.prescriptions=prescriptions;}
 @Transactional public MedicalRecord save(MedicalRecord m){MedicalRecordEntity e=jpa.findById(m.getId()).orElseGet(MedicalRecordEntity::new);e.id=m.getId();e.patientId=m.getPatientId();e.doctorId=m.getDoctorId();e.createdAt=m.getCreatedAt();e.systolic=m.getSystolic();e.diastolic=m.getDiastolic();e.temperature=m.getTemperature();e.heartRate=m.getHeartRate();e.spo2=m.getSpo2();e.triage=m.getTriage().name();e.clinicalAlert=m.isClinicalAlert();e.closed=m.isClosed();e.diagnosisCode=m.getDiagnosisCode();e.evolution=m.getEvolution();e.disabilityDays=m.getDisabilityDays();e.allergies=String.join("\n",m.getAllergyTerms());jpa.save(e);prescriptions.deleteByEncounterId(m.getId());for(String medicine:m.getPrescriptions()){MedicalPrescriptionEntity p=new MedicalPrescriptionEntity();p.id=UUID.randomUUID();p.encounterId=m.getId();p.medication=medicine;p.issuedAt=m.getCreatedAt();p.active=true;prescriptions.save(p);}return m;}
 public Optional<MedicalRecord> findById(UUID id){return jpa.findById(id).map(this::toDomain);} public List<MedicalRecord> findByPatient(UUID id){return jpa.findByPatientId(id).stream().map(this::toDomain).toList();} public List<MedicalRecord> findByDoctor(UUID id){return jpa.findByDoctorId(id).stream().map(this::toDomain).toList();}
 private MedicalRecord toDomain(MedicalRecordEntity e){MedicalRecord m=new MedicalRecord(e.id,e.patientId,e.doctorId,e.systolic,e.diastolic,e.temperature,e.heartRate,e.spo2,e.createdAt,e.allergies==null?List.of():Arrays.asList(e.allergies.split("\\n")));for(MedicalPrescriptionEntity p:prescriptions.findByEncounterIdAndActiveTrue(e.id))m.restorePrescription(p.medication);if(e.closed)m.close(e.diagnosisCode,e.evolution,e.disabilityDays);return m;}
}
